#!/usr/bin/env node
/**
 * Wave 04A — Remaining Remediation Inventory
 *
 * Parses the remediation items from the LOCKED-CONTRACTS-SUMMARY.md report
 * (which was generated by verify-locked-contracts.mjs using actual DOCX binary
 * comparison), then produces structured inventories.
 *
 * Output:
 *   docs/audit/docx/reports/REMAINING-REMEDIATION-INVENTORY.md
 *   docs/audit/docx/reports/remaining-remediation-inventory.json
 *
 * Usage:
 *   node scripts/docx-contract/list-remaining-remediation.mjs
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..", "..");
const REPORTS_DIR = path.join(ROOT, "docs", "audit", "docx", "reports");
const SUMMARY_PATH = path.join(REPORTS_DIR, "LOCKED-CONTRACTS-SUMMARY.md");

const RISK_MAP = {
  "document.fullDocumentCode": { risk: "low", suggested: "rename-placeholder" },
  "document.fullDocumentCode2": { risk: "low", suggested: "rename-placeholder" },
  "document.issueDate": { risk: "low", suggested: "rename-placeholder" },
  "document.issuePlaceAndDateLine": { risk: "low", suggested: "rename-placeholder" },
  "person.religion": { risk: "medium", suggested: "needs-human-review" },
  "recipients.personLine": { risk: "low", suggested: "add-placeholder" },
  "agency.nameUpper": { risk: "medium", suggested: "add-placeholder" },
  "agency.bodyName": { risk: "medium", suggested: "add-placeholder" },
  "agency.parentNameUpper": { risk: "medium", suggested: "add-placeholder" },
  "decision.decisionLine": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine2": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine3": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine4": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine5": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine6": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine7": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine8": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine9": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine10": { risk: "low", suggested: "rename-placeholder" },
  "decision.decisionLine11": { risk: "low", suggested: "rename-placeholder" },
  "document.issueDate4": { risk: "low", suggested: "rename-placeholder" },
  "document.issueDate6": { risk: "low", suggested: "rename-placeholder" },
  "document.issueDate7": { risk: "low", suggested: "rename-placeholder" },
  "official.issuerTitle": { risk: "medium", suggested: "add-placeholder" },
  "sourceAssignment.article1Line": { risk: "medium", suggested: "add-placeholder" },
  "sourceAssignment.article2Line": { risk: "medium", suggested: "add-placeholder" },
  "sourceAssignment.article3Line": { risk: "medium", suggested: "add-placeholder" },
  "crimeReport.content": { risk: "medium", suggested: "add-placeholder" },
  "crimeReport.attachedItemsDescription": { risk: "medium", suggested: "add-placeholder" },
  "reception.startedAtDay": { risk: "medium", suggested: "add-placeholder" },
  "reception.startedAtMonth": { risk: "medium", suggested: "add-placeholder" },
  "reception.startedAtTimeText": { risk: "medium", suggested: "add-placeholder" },
  "reception.startedAtYear": { risk: "medium", suggested: "add-placeholder" },
  "reception.endedAtDay": { risk: "medium", suggested: "add-placeholder" },
  "reception.endedAtMonth": { risk: "medium", suggested: "add-placeholder" },
  "reception.endedAtTimeText": { risk: "medium", suggested: "add-placeholder" },
  "reception.endedAtYear": { risk: "medium", suggested: "add-placeholder" },
  "reception.locationName": { risk: "medium", suggested: "add-placeholder" },
  "sourceTransfer.attachedItemsDescription": { risk: "medium", suggested: "add-placeholder" },
};

function defaultRisk(issueCode, path) {
  if (issueCode === "TEMPLATE_PLACEHOLDER_WITHOUT_SLOT") return "medium";
  if (issueCode === "CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER") return "medium";
  if (issueCode === "BINDING_WITHOUT_TEMPLATE_PLACEHOLDER") return "medium";
  return "medium";
}

function defaultSuggested(issueCode) {
  if (issueCode === "TEMPLATE_PLACEHOLDER_WITHOUT_SLOT") return "add-placeholder";
  if (issueCode === "CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER") return "add-placeholder";
  if (issueCode === "BINDING_WITHOUT_TEMPLATE_PLACEHOLDER") return "add-placeholder";
  return "needs-human-review";
}

/**
 * Parse remediation section from LOCKED-CONTRACTS-SUMMARY.md.
 * Format:
 *   - ⚠️ [BM-xxx] ISSUE_CODE
 *     - field1, field2
 */
function parseRemediationSection(md) {
  const remediation = [];
  const lines = md.split("\n");
  let inRemediation = false;

  for (const line of lines) {
    if (line.startsWith("## Remediation Required")) {
      inRemediation = true;
      continue;
    }
    if (line.startsWith("## Warnings")) {
      inRemediation = false;
      continue;
    }
    if (!inRemediation) continue;

    // Line: - ⚠️ [BM-xxx] ISSUE_CODE
    const issueMatch = line.match(/^\s*-\s*⚠️\s*\[([^\]]+)\]\s*([A-Z_]+)/);
    if (issueMatch) {
      const templateCode = issueMatch[1];
      const issueCode = issueMatch[2];

      // Collect subsequent indented lines as paths.
      const paths = [];
      const idx = lines.indexOf(line);
      for (let i = idx + 1; i < lines.length; i++) {
        const nextLine = lines[i];
        if (!nextLine.startsWith("  - ")) break;
        const pathLine = nextLine.replace(/^\s*-\s*/, "").trim();
        for (const p of pathLine.split(",").map((s) => s.trim()).filter(Boolean)) {
          paths.push(p);
        }
      }

      for (const path of paths) {
        const known = RISK_MAP[path] ?? {};
        remediation.push({
          templateCode,
          sourceId: "",
          issueCode,
          path,
          suggestedAction: known.suggested ?? defaultSuggested(issueCode),
          risk: known.risk ?? defaultRisk(issueCode, path),
          reason: `DOCX template needs ${known.suggested ?? defaultSuggested(issueCode)}: ${path}`,
          evidence: `${issueCode}: ${path}`,
        });
      }
    }
  }

  return remediation;
}

function classifyByType(items) {
  return {
    TEMPLATE_PLACEHOLDER_WITHOUT_SLOT: items.filter((i) => i.issueCode === "TEMPLATE_PLACEHOLDER_WITHOUT_SLOT"),
    CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER: items.filter((i) => i.issueCode === "CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER"),
    BINDING_WITHOUT_TEMPLATE_PLACEHOLDER: items.filter((i) => i.issueCode === "BINDING_WITHOUT_TEMPLATE_PLACEHOLDER"),
    other: items.filter((i) =>
      !["TEMPLATE_PLACEHOLDER_WITHOUT_SLOT", "CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER", "BINDING_WITHOUT_TEMPLATE_PLACEHOLDER"].includes(i.issueCode)
    ),
  };
}

function generateMarkdownReport(itemsByType, allItems) {
  const md = [
    "# Remaining Remediation Inventory (Wave 04A)",
    "",
    `Generated: ${new Date().toISOString()}`,
    "",
    "## Summary",
    "",
    `| Issue Type | Count |`,
    `|---|---|`,
    `| TEMPLATE_PLACEHOLDER_WITHOUT_SLOT | ${itemsByType.TEMPLATE_PLACEHOLDER_WITHOUT_SLOT.length} |`,
    `| CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER | ${itemsByType.CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER.length} |`,
    `| BINDING_WITHOUT_TEMPLATE_PLACEHOLDER | ${itemsByType.BINDING_WITHOUT_TEMPLATE_PLACEHOLDER.length} |`,
    `| Other | ${itemsByType.other.length} |`,
    `| **Total** | **${allItems.length}** |`,
    "",
    "## Risk Breakdown",
    "",
    `| Risk | Count |`,
    `|---|---|`,
    `| Low | ${allItems.filter((i) => i.risk === "low").length} |`,
    `| Medium | ${allItems.filter((i) => i.risk === "medium").length} |`,
    `| High | ${allItems.filter((i) => i.risk === "high").length} |`,
    "",
  ];

  const sections = [
    { key: "TEMPLATE_PLACEHOLDER_WITHOUT_SLOT", title: "TEMPLATE_PLACEHOLDER_WITHOUT_SLOT" },
    { key: "CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER", title: "CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER" },
    { key: "BINDING_WITHOUT_TEMPLATE_PLACEHOLDER", title: "BINDING_WITHOUT_TEMPLATE_PLACEHOLDER" },
  ];

  for (const { key, title } of sections) {
    const bucket = itemsByType[key];
    if (bucket.length === 0) continue;

    md.push(`## ${title}`, "");

    const byCode = {};
    for (const item of bucket) {
      if (!byCode[item.templateCode]) byCode[item.templateCode] = [];
      byCode[item.templateCode].push(item);
    }

    for (const [code, codeItems] of Object.entries(byCode)) {
      md.push(`### ${code}`, "");
      for (const item of codeItems) {
        md.push(
          `- \`${item.path}\` — ${item.risk.toUpperCase()} risk · \`${item.suggestedAction}\``,
          `  - Reason: ${item.reason}`,
          `  - Evidence: ${item.evidence}`,
          "",
        );
      }
    }
  }

  // Recommended Wave 04B: lowest risk first, grouped by template.
  const sorted = [...allItems].sort((a, b) => {
    const riskOrder = { low: 0, medium: 1, high: 2 };
    if (riskOrder[a.risk] !== riskOrder[b.risk]) return riskOrder[a.risk] - riskOrder[b.risk];
    return a.templateCode.localeCompare(b.templateCode);
  });

  md.push("## Recommended Wave 04B (lowest risk first)", "");
  const byCodeSorted = {};
  for (const item of sorted) {
    if (!byCodeSorted[item.templateCode]) byCodeSorted[item.templateCode] = [];
    byCodeSorted[item.templateCode].push(item);
  }
  for (const [code, codeItems] of Object.entries(byCodeSorted)) {
    md.push(`### ${code}`);
    for (const item of codeItems) {
      md.push(
        `  - \`${item.path}\` — ${item.risk} risk · \`${item.suggestedAction}\` (\`${item.issueCode}\`)`,
      );
    }
  }

  return md.join("\n");
}

async function main() {
  if (!fs.existsSync(SUMMARY_PATH)) {
    console.error("Summary not found. Run verify-locked first:");
    console.error("  pnpm audit:docx:verify-locked");
    process.exit(1);
  }

  const md = fs.readFileSync(SUMMARY_PATH, "utf8");
  const items = parseRemediationSection(md);
  console.log(`Found ${items.length} remediation items from summary`);

  if (items.length === 0) {
    console.error("No remediation items found in summary. Is it up to date?");
    process.exit(1);
  }

  const itemsByType = classifyByType(items);

  // Write JSON.
  const jsonOut = path.join(REPORTS_DIR, "remaining-remediation-inventory.json");
  fs.writeFileSync(
    jsonOut,
    JSON.stringify(
      {
        generated: new Date().toISOString(),
        source: "LOCKED-CONTRACTS-SUMMARY.md",
        total: items.length,
        byType: {
          TEMPLATE_PLACEHOLDER_WITHOUT_SLOT: itemsByType.TEMPLATE_PLACEHOLDER_WITHOUT_SLOT.length,
          CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER: itemsByType.CONTRACT_SLOT_WITHOUT_TEMPLATE_PLACEHOLDER.length,
          BINDING_WITHOUT_TEMPLATE_PLACEHOLDER: itemsByType.BINDING_WITHOUT_TEMPLATE_PLACEHOLDER.length,
          other: itemsByType.other.length,
        },
        byRisk: {
          low: items.filter((i) => i.risk === "low").length,
          medium: items.filter((i) => i.risk === "medium").length,
          high: items.filter((i) => i.risk === "high").length,
        },
        items,
      },
      null,
      2,
    ),
    "utf8",
  );
  console.log(`  JSON: ${jsonOut}`);

  // Write Markdown.
  const mdReport = generateMarkdownReport(itemsByType, items);
  const mdOut = path.join(REPORTS_DIR, "REMAINING-REMEDIATION-INVENTORY.md");
  fs.writeFileSync(mdOut, mdReport, "utf8");
  console.log(`  Markdown: ${mdOut}`);

  // Console summary.
  console.log("\nRemediation Summary:");
  console.log(`  Total: ${items.length}`);
  console.log(`  Low risk:    ${items.filter((i) => i.risk === "low").length}`);
  console.log(`  Medium risk: ${items.filter((i) => i.risk === "medium").length}`);
  console.log(`  High risk:   ${items.filter((i) => i.risk === "high").length}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
